import java.io.*;
import java.util.*;

public class F {
    public static void main(String[] args) throws Exception {
        new F().execute();
    }

    void execute() throws Exception {
        InputStream inputStream = System.in;
        PrintWriter output = new PrintWriter(System.out);
        Scanner scanner = new Scanner(inputStream);
        int n = scanner.nextInt();
        int K = scanner.nextInt();
        int[][] ts = new int[K][2];
        long total = 0;
        for (int i = 0; i < K; i++) {
            ts[i][0] = scanner.nextInt();
            ts[i][1] = scanner.nextInt();
            total += ts[i][1] - ts[i][0];
        }
        int[] dpe = new int[n + 1];
        int[] dpo = new int[n + 1];
        Arrays.fill(dpe, 99999999);
        Arrays.fill(dpo, 99999999);
        if (ts[0][0] > n) {
            output.println("Hungry");
            output.flush();
            return;
        }
        dpe[ts[0][0]] = 0;
        for (int i = 0; i < K; i++) {
            int[] newDpo = new int[n + 1];
            int[] newDpe = new int[n + 1];
            Arrays.fill(newDpo, 99999999);
            Arrays.fill(newDpe, 99999999);
            Deque<Integer> deque = new ArrayDeque<>();
            int w = ts[i][1] - ts[i][0];
            for (int j = 0; j <= n; j++) {
                while (!deque.isEmpty() && dpe[deque.peekLast()] >= dpe[j]) deque.pollLast();
                while (!deque.isEmpty() && deque.peekFirst() < j - w) deque.pollFirst();
                deque.offerLast(j);
                newDpo[j] = Math.min(newDpo[j], dpe[deque.peekFirst()] + 1);
                if (j + w <= n) newDpe[j + w] = Math.min(newDpe[j + w], dpe[j]);
            }
            deque.clear();
            for (int j = 0; j <= n; j++) {
                while (!deque.isEmpty() && dpo[deque.peekLast()] >= dpo[j]) deque.pollLast();
                while (!deque.isEmpty() && deque.peekFirst() < j - w) deque.pollFirst();
                deque.offerLast(j);
                newDpe[j] = Math.min(newDpe[j], dpo[deque.peekFirst()] + 1);
                newDpo[j] = Math.min(newDpo[j], dpo[j]);
            }
            dpo = newDpo;
            dpe = newDpe;
            for (int j = 0; j <= n; j++) {
                dpe[j] = Math.min(dpe[j], dpo[j] + 1);
                dpo[j] = Math.min(dpo[j], dpe[j] + 1);
            }
            int s = (i == K - 1 ? 2 * n : ts[i + 1][0]) - ts[i][1];
            for (int j = n; j >= s; j--) {
                dpe[j] = dpe[j - s];
            }
            for (int j = Math.min(n, s - 1); j >= 0; j--) {
                dpe[j] = 99999999;
            }
        }
        int ans = Math.min(dpe[n], dpo[n]);
        if (ans >= 9999999) {
            output.println("Hungry");
        } else {
            output.println("Full");
            output.println(ans);
        }
        output.flush();
    }
}
